package api

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

// Presets: virtual models over the one set of weights.
//
// llama-server's `--models-preset` file is an INI of sections, one a model,
// and this server reads the same file. A section here carries no weights of
// its own: it is a name a request's `model` field can ask for, and a set of
// sampling and template defaults that request then gets. Whatever the
// request names itself wins, field by field, so a preset is a default and
// never an override -- a client that sends `temperature: 0` to "coding" gets
// greedy decoding, not the preset's 1.0.
//
// A key this server does not know is refused when the file is loaded rather
// than ignored, for the reason every other refusal in this package is there:
// a setting that is read and does nothing is a setting whoever wrote it
// believes is in force.

// Preset is one section of the file.
type Preset struct {
	Name            string
	Temperature     *float64
	TopP            *float64
	TopK            *int
	MinP            *float64
	RepeatPenalty   *float64
	PresencePenalty *float64
	// Kwargs is `chat-template-kwargs`, with `reasoning` folded in as
	// `enable_thinking`.
	Kwargs map[string]json.RawMessage
}

// LoadPresets reads a preset file.
func LoadPresets(path string) ([]Preset, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	ps, err := ParsePresets(f)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return ps, nil
}

// ParsePresets reads the INI. llama-server spells its keys as its command
// line does, and the file this was written for mixes `top_p` and `top-p`, so
// both are taken; `;` and `#` start a comment line.
func ParsePresets(r io.Reader) ([]Preset, error) {
	var out []Preset
	var cur *Preset
	sc := bufio.NewScanner(r)
	for n := 1; sc.Scan(); n++ {
		line := strings.TrimSpace(sc.Text())
		if line == "" || line[0] == ';' || line[0] == '#' {
			continue
		}
		if line[0] == '[' {
			if !strings.HasSuffix(line, "]") {
				return nil, fmt.Errorf("line %d: unterminated section header", n)
			}
			name := strings.TrimSpace(line[1 : len(line)-1])
			if name == "" {
				return nil, fmt.Errorf("line %d: empty section name", n)
			}
			for _, p := range out {
				if p.Name == name {
					return nil, fmt.Errorf("line %d: section [%s] appears twice", n, name)
				}
			}
			out = append(out, Preset{Name: name})
			cur = &out[len(out)-1]
			continue
		}
		key, val, ok := strings.Cut(line, "=")
		if !ok {
			return nil, fmt.Errorf("line %d: expected key = value", n)
		}
		if cur == nil {
			return nil, fmt.Errorf("line %d: %q is outside any section", n, strings.TrimSpace(key))
		}
		if err := cur.set(strings.TrimSpace(key), strings.TrimSpace(val)); err != nil {
			return nil, fmt.Errorf("line %d: [%s] %v", n, cur.Name, err)
		}
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// set applies one key.
func (p *Preset) set(key, val string) error {
	float := func(dst **float64) error {
		v, err := strconv.ParseFloat(val, 64)
		if err != nil {
			return fmt.Errorf("%s: %v", key, err)
		}
		*dst = &v
		return nil
	}
	switch strings.ReplaceAll(strings.ToLower(key), "_", "-") {
	case "temperature", "temp":
		return float(&p.Temperature)
	case "top-p":
		return float(&p.TopP)
	case "min-p":
		return float(&p.MinP)
	case "repeat-penalty", "repetition-penalty":
		return float(&p.RepeatPenalty)
	case "presence-penalty":
		return float(&p.PresencePenalty)
	case "top-k":
		v, err := strconv.Atoi(val)
		if err != nil {
			return fmt.Errorf("%s: %v", key, err)
		}
		p.TopK = &v
		return nil
	case "chat-template-kwargs":
		var kw map[string]json.RawMessage
		if err := json.Unmarshal([]byte(val), &kw); err != nil {
			return fmt.Errorf("%s: %v", key, err)
		}
		for k, v := range kw {
			if err := p.kwarg(k, v); err != nil {
				return err
			}
		}
		// The same check a request's kwargs get, so a typo fails here.
		_, err := (&CompletionRequest{ChatTemplateKwargs: p.Kwargs}).Thinking()
		return err
	case "reasoning":
		// llama-server's `--reasoning on|off|auto`: whether the template
		// opens a think block, which here is `enable_thinking`.
		switch strings.ToLower(val) {
		case "on":
			return p.kwarg("enable_thinking", json.RawMessage("true"))
		case "off":
			return p.kwarg("enable_thinking", json.RawMessage("false"))
		case "auto":
			return nil
		}
		return fmt.Errorf("reasoning is %q; it takes on, off or auto", val)
	}
	return fmt.Errorf("%q is not a setting this server applies per model; it takes temperature, top-p, top-k, "+
		"min-p, repeat-penalty, presence-penalty, chat-template-kwargs and reasoning", key)
}

// kwarg sets one template variable, refusing one set twice to two different
// values -- `reasoning = off` beside `enable_thinking: true` is a file that
// does not say what it wants.
func (p *Preset) kwarg(k string, v json.RawMessage) error {
	if p.Kwargs == nil {
		p.Kwargs = map[string]json.RawMessage{}
	}
	if old, ok := p.Kwargs[k]; ok && string(old) != string(v) {
		return fmt.Errorf("%s is set to both %s and %s", k, old, v)
	}
	p.Kwargs[k] = v
	return nil
}

// Apply fills in whatever the request left unset.
func (p *Preset) Apply(req *CompletionRequest) {
	fill := func(dst **float64, src *float64) {
		if *dst == nil && src != nil {
			v := *src
			*dst = &v
		}
	}
	fill(&req.Temperature, p.Temperature)
	fill(&req.TopP, p.TopP)
	fill(&req.MinP, p.MinP)
	fill(&req.RepeatPenalty, p.RepeatPenalty)
	fill(&req.PresencePenalty, p.PresencePenalty)
	if req.TopK == nil && p.TopK != nil {
		v := *p.TopK
		req.TopK = &v
	}
	for k, v := range p.Kwargs {
		if _, ok := req.ChatTemplateKwargs[k]; ok {
			continue
		}
		if req.ChatTemplateKwargs == nil {
			req.ChatTemplateKwargs = map[string]json.RawMessage{}
		}
		req.ChatTemplateKwargs[k] = v
	}
}

// preset is the preset a request's model names, or nil.
func (s *Server) preset(model string) *Preset {
	for i := range s.Presets {
		if s.Presets[i].Name == model {
			return &s.Presets[i]
		}
	}
	return nil
}

// completionModel applies the preset the request names, if it names one, and
// returns the model id the response reports: the preset's name, since that
// is what decided how the answer was sampled, or the backend's own id.
func (s *Server) completionModel(req *CompletionRequest) string {
	if p := s.preset(req.Model); p != nil {
		p.Apply(req)
		return p.Name
	}
	return modelID(s.Completion, req.Model)
}
		}
	}
	return b.String()
}

// NonText is the first content block that is not text, or the empty string.
// It is what the chat handler refuses on: there is no vision tower in this
// repository, so an image block would be dropped silently and answered about
// as though it had never been sent.
func (c MessageContent) NonText() string {
	for _, part := range c {
		if part.Type != "" && part.Type != "text" {
			return part.Type
		}
	}
	return ""
}

// Thinking is a request's reasoning switches, resolved from the two
// vocabularies it can arrive in: OpenAI's `reasoning_effort` and the
// template's own variables in `chat_template_kwargs`.
type Thinking struct {
	// Off is `enable_thinking=false`.
	Off bool
	// Effort is "", "low", "medium", "high" or "xhigh"; empty is the
	// template's default.
	Effort string
	// DropHistory is `preserve_thinking=false`.
	DropHistory bool
}

// Thinking resolves the request's reasoning switches.
//
// The top-level `reasoning_effort` is always the client's own -- a preset
// only ever fills in `chat_template_kwargs` -- so when it is set it decides
// on and off outright. Otherwise `enable_thinking` does, and a
// `reasoning_effort` of "none" in the kwargs means off only when
// `enable_thinking` is absent: a client that sends `enable_thinking: true`
// to a non-thinking preset gets thinking, whatever effort the preset named.
func (r *CompletionRequest) Thinking() (Thinking, error) {
	var t Thinking
	var enable *bool
	var effort string
	for k, v := range r.ChatTemplateKwargs {
		var err error
		switch k {
		case "enable_thinking":
			var b bool
			err = json.Unmarshal(v, &b)
			enable = &b
		case "preserve_thinking":
			var b bool
			err = json.Unmarshal(v, &b)
			t.DropHistory = !b
		case "reasoning_effort":
			err = json.Unmarshal(v, &effort)
		default:
			return t, fmt.Errorf("chat_template_kwargs.%s is not a variable this checkpoint's template reads; "+
				"it takes enable_thinking, preserve_thinking and reasoning_effort", k)
		}
		if err != nil {
			return t, fmt.Errorf("chat_template_kwargs.%s: %v", k, err)
		}
	}
	effort = strings.ToLower(effort)
	off := effort == "none" || effort == "minimal"
	if enable != nil {
		off = !*enable
	}
	if r.ReasoningEffort != "" {
		effort = strings.ToLower(r.ReasoningEffort)
		off = effort == "none" || effort == "minimal"
	}
	t.Off = off
	if !off && effort != "none" && effort != "minimal" {
		t.Effort = effort
	}
	return t, nil
}
