func (s *Server) handleChatCompletions(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if s.Completion == nil {
		notLoaded(ctx, w, "the language model", "-llm")
		return
	}
	var req CompletionRequest
	if !decodeJSON(ctx, w, r, &req) {
		return
	}
	model := s.completionModel(&req)
	if !validCompletion(ctx, w, &req) {
		return
	}

	id := "chatcmpl-" + randomID()
	created := time.Now().Unix()
	if req.Stream {
		s.streamCompletion(w, r, &req, id, model, created)
		return
	}

	var content, reasoning strings.Builder
	res, err := s.Completion.Complete(r.Context(), &req, func(d Delta) error {
		content.WriteString(d.Content)
		reasoning.WriteString(d.ReasoningContent)
		return nil
	})
	if err != nil {
		backendError(ctx, w, "chat completion", err)
		return
	}
	msg := &Delta{
		Role:             "assistant",
		ReasoningContent: reasoning.String(),
		Content:          content.String(),
		ToolCalls:        res.ToolCalls,
	}
	usage := res.Usage
	writeJSON(w, http.StatusOK, CompletionResponse{
		ID:      id,
		Object:  "chat.completion",
		Created: created,
		Model:   model,
		Choices: []Choice{{Index: 0, Message: msg, FinishReason: &res.FinishReason}},
		Usage:   &usage,
	})
}

